import React, { useState } from 'react';
import { QuizProvider, useQuiz } from './context/QuizContext';
import TopicSelectionScreen from './components/TopicSelectionScreen';
import LoadingScreen from './components/LoadingScreen';
import QuizScreen from './components/QuizScreen';
import ResultsScreen from './components/ResultsScreen';
import ChatbotInterface from './components/ChatbotInterface';
import ChatbotDemo from './components/ChatbotDemo';

const AppContent = () => {
  const { state } = useQuiz();
  const [mode, setMode] = useState('quiz'); // 'quiz', 'chatbot', or 'demo'

  const renderScreen = () => {
    if (mode === 'demo') {
      return <ChatbotDemo />;
    }
    
    if (mode === 'chatbot' && state.selectedTopic) {
      return <ChatbotInterface />;
    }

    switch (state.currentScreen) {
      case 'topic-selection':
        return <TopicSelectionScreen />;
      case 'loading':
        return <LoadingScreen />;
      case 'quiz':
        return <QuizScreen />;
      case 'results':
        return <ResultsScreen />;
      default:
        return <TopicSelectionScreen />;
    }
  };

  return (
    <div className="container">
      {/* Mode Selector */}
      {state.currentScreen === 'topic-selection' && (
        <div style={{ 
          marginBottom: '20px', 
          display: 'flex', 
          justifyContent: 'center',
          gap: '10px'
        }}>
          <button
            onClick={() => setMode('quiz')}
            style={{
              padding: '10px 20px',
              background: mode === 'quiz' ? '#667eea' : '#e2e8f0',
              color: mode === 'quiz' ? 'white' : '#4a5568',
              border: 'none',
              borderRadius: '25px',
              cursor: 'pointer',
              fontSize: '1rem',
              fontWeight: '600',
              transition: 'all 0.3s ease'
            }}
          >
            📝 Quiz Mode
          </button>
          <button
            onClick={() => setMode('chatbot')}
            style={{
              padding: '10px 20px',
              background: mode === 'chatbot' ? '#667eea' : '#e2e8f0',
              color: mode === 'chatbot' ? 'white' : '#4a5568',
              border: 'none',
              borderRadius: '25px',
              cursor: 'pointer',
              fontSize: '1rem',
              fontWeight: '600',
              transition: 'all 0.3s ease'
            }}
          >
            🤖 AI Chat Mode
          </button>
          <button
            onClick={() => setMode('demo')}
            style={{
              padding: '10px 20px',
              background: mode === 'demo' ? '#667eea' : '#e2e8f0',
              color: mode === 'demo' ? 'white' : '#4a5568',
              border: 'none',
              borderRadius: '25px',
              cursor: 'pointer',
              fontSize: '1rem',
              fontWeight: '600',
              transition: 'all 0.3s ease'
            }}
          >
            🧪 Test Chatbot
          </button>
        </div>
      )}

      {state.error && (
        <div className="error-message">
          <strong>Error:</strong> {state.error}
          <button 
            onClick={() => window.location.reload()} 
            style={{
              marginLeft: '10px',
              padding: '5px 10px',
              background: '#667eea',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Retry
          </button>
        </div>
      )}
      {renderScreen()}
    </div>
  );
};

const App = () => {
  return (
    <QuizProvider>
      <AppContent />
    </QuizProvider>
  );
};

export default App;
